// Function to search Google Hotels for a city and return top results
async function searchHotels(cityQuery) {
  const url = `https://www.google.com/travel/hotels/${encodeURIComponent(cityQuery)}?hl=en-GB&curr=GBP&dates=2026-11-21,2026-11-28`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });

  const curUrl = await browserjs(tabId, () => window.location.href);
  const hotels = await browserjs(tabId, () => {
    // Collect hotel cards
    const cards = [];
    const elements = Array.from(document.querySelectorAll('[role="listitem"], [data-result-index], div.l5c1fd, [jscontroller]'));
    // Find headings or links with hotel names and prices
    const nameEls = Array.from(document.querySelectorAll('h2, h3, a[href*="hotels"]'));

    // Look at text blocks containing £
    const candidates = Array.from(document.querySelectorAll('div, a')).filter(el => {
      const t = el.innerText || '';
      return t.includes('£') && (t.includes('hotel') || t.includes('Hotel') || t.includes('★') || t.includes('/5'));
    });

    // Simpler: find all hotel name headers and nearest price
    const hList = Array.from(document.querySelectorAll('h2, h3'));
    for (const h of hList) {
      const name = h.innerText.trim();
      if (!name || name.length < 3 || name.length > 50) continue;
      // check container for price and rating
      let p = h;
      for (let i = 0; i < 5; i++) {
        if (!p.parentElement) break;
        p = p.parentElement;
        const pt = p.innerText;
        const priceMatch = pt.match(/£(\d+)/);
        const ratingMatch = pt.match(/(\d\.\d)\s*\(\d+/);
        if (priceMatch && !name.includes('£')) {
          cards.push({
            name,
            priceNight: `£${priceMatch[1]}`,
            rating: ratingMatch ? ratingMatch[1] : null,
            snippet: pt.slice(0, 150).replace(/\n+/g, ' | ')
          });
          break;
        }
      }
    }
    return {
      url: window.location.href,
      cards: cards.slice(0, 10)
    };
  });
